targets.expr:
sum by (uri, method) (
  increase(
    http_server_requests_seconds_count{
      application="$service", namespace="$namespace", 
      status=~"2..|3.."
    }[$__range]
  )
)

sum by (uri, method) (
  increase(
    http_server_requests_seconds_count{
      application="$service", namespace="$namespace", 
      status=~"4..|5.."
    }[$__range]
  )
)

sum by (uri, method) (
  increase (
    http_server_requests_seconds_sum{application="$service", namespace="$namespace"}[$__range]
  )
)
/
sum by (uri, method) (
  increase (
    http_server_requests_seconds_count{application="$service", namespace="$namespace"}[$__range]
  )
)
